// === Tab: sketch152954 ===
let animation = 0.0;
let circleSize = 50.0;
let col = 1;
let drawCirlces = true;
let drawDots = true;

function setup() {
  createCanvas(400, 400);
  noFill();
  colorMode(RGB, 1);
}

function draw() {
  animation += 0.1;

  background(abs(col -1));

  for (x = 0; x < (width/circleSize*2.0) + 1; x++) {
    for (y = 0; y < height/circleSize*2.0 + 1; y++) {

      pushMatrix();

      translate(x * circleSize/2, y * circleSize/2);
      if (drawCirlces) {
        noFill();
        stroke(col);
        ellipse(0, 0, circleSize/2, circleSize/2);
      }

      rotate((x/circleSize * TWO_PI * 4) + animation + (y/circleSize * circleSize));

      translate(circleSize/4.0, 0);

      if (drawDots) {
        fill(col);
        ellipse(0, 0, circleSize/8, circleSize/8);
      }

      popMatrix();
    }
  }
}

function keyPressed() {
  if (keyCode == 73) {
    col++;
    col %= 2;
  }
  else if (keyCode == 67) {
    drawCirlces = !drawCirlces;
  }
  else if(keyCode == 68){
    drawDots = ! drawDots;
  }
}

